const errorData = $input.item.json;
const execution = errorData.execution || {};
const workflow = errorData.workflow || {};

const failedNodeName = execution.lastNodeExecuted || 'Unknown Node';
const errorMsg = execution.error ? (execution.error.message || JSON.stringify(execution.error)) : 'Unknown execution failure';
const workflowName = workflow.name || 'Enterprise Workflow';
const workflowId = workflow.id || 'N/A';
const executionId = execution.id || 'N/A';

const rawUrl = $env.WEBHOOK_URL || 'http://localhost:5678';
const n8nBaseUrl = rawUrl.split('/webhook')[0];
const executionUrl = n8nBaseUrl + '/workflow/' + workflowId + '/executions/' + executionId;

const slackBlocks = [
  {
    type: 'header',
    text: {
      type: 'plain_text',
      text: 'Critical Workflow Execution Failure',
      emoji: true
    }
  },
  {
    type: 'section',
    fields: [
      { type: 'mrkdwn', text: '*Workflow:* ' + workflowName },
      { type: 'mrkdwn', text: '*Failed Node:* ' + failedNodeName },
      { type: 'mrkdwn', text: '*Execution ID:* <' + executionUrl + '|#' + executionId + '>' },
      { type: 'mrkdwn', text: '*Timestamp:* ' + new Date().toISOString() }
    ]
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: '*Error Message:*\n```' + errorMsg.slice(0, 500) + '```'
    }
  },
  {
    type: 'actions',
    elements: [
      {
        type: 'button',
        text: { type: 'plain_text', text: 'View Execution in n8n' },
        url: executionUrl,
        style: 'danger'
      }
    ]
  }
];

return [{
  json: {
    workflow_name: workflowName,
    workflow_id: workflowId,
    execution_id: executionId,
    failed_node: failedNodeName,
    error_message: errorMsg,
    execution_url: executionUrl,
    slack_payload: { blocks: slackBlocks }
  }
}];
